mapper.select:
SELECT l.id, l.rule_id, l.rule_name, l.trigger_code, l.object_key, l.object_label, l.store_id, l.result, l.match_detail, l.cost_ms,
       l.error_msg, l.retry_count, l.actions_json, l.create_time, l.update_time, s.name AS store_name
FROM ecom_auto_log l
LEFT JOIN ecom_store s ON s.id = l.store_id

    AND l.rule_id = #{q.ruleId}
    AND l.trigger_code = #{q.trigger}
    AND l.result = #{q.result}
    AND l.result IN ('SUCCESS', 'PARTIAL', 'FAILED')
    AND l.store_id = #{q.storeId}
    AND l.create_time >= #{q.beginDate}
    AND l.create_time < #{q.endExclusive}

        AND (l.object_label LIKE CONCAT('%', #{q.keyword}, '%') OR l.object_key LIKE CONCAT('%', #{q.keyword}, '%')
             OR l.rule_name LIKE CONCAT('%', #{q.keyword}, '%'))


ORDER BY l.create_time DESC, l.id DESC

SELECT result AS "result", COUNT(*) AS "cnt" FROM ecom_auto_log
WHERE create_time >= #{since}
AND rule_id = #{ruleId}
GROUP BY result
